def decide_next_move(state):
    obstacles = {
        "FORWARD": not state["front_blocked"],
        "LEFT": not state["left_blocked"],
        "RIGHT": not state["right_blocked"]
    }

    for direction in ["FORWARD", "LEFT", "RIGHT"]:
        if state[f"goal_{direction}"]:
            if obstacles[direction]:
                return direction

    if state["goal_ahead"]:
        if not state["front_blocked"]:
            return "FORWARD"
    elif state["goal_on_left"]:
        if not state["left_blocked"]:
            return "LEFT"
    elif state["goal_on_right"]:
        if not state["right_blocked"]:
            return "RIGHT"

    return navigate(obstacles)

navigate = lambda obstacles: "STOP" if all(obstacles.values()) else navigate(obstacles)
